package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.phys.*;import net.minecraft.world.level.block.state.*;import java.lang.reflect.*;import java.util.*;
/** SBW native hit events plus vanilla/TaCZ block hits converge here; an impact is charged once. */
public final class Ps01Compat{
 public static final ThreadLocal<Boolean> CHECKING=ThreadLocal.withInitial(()->false);
 private static final Map<Class<?>,Method[]>METHODS=new HashMap<>();
 public static void register(){try{Class<?> c=Class.forName("com.atsuishio.superbwarfare.api.event.ProjectileHitEvent$HitBlock");Method projectile=c.getMethod("getProjectile"),vec=c.getMethod("getHitVec"),pos=c.getMethod("getPos");net.minecraftforge.common.MinecraftForge.EVENT_BUS.addListener(net.minecraftforge.eventbus.api.EventPriority.NORMAL,false,(Class)c,(java.util.function.Consumer<net.minecraftforge.eventbus.api.Event>)(e->{try{Entity p=(Entity)projectile.invoke(e);impact(p,new BlockHitResult((Vec3)vec.invoke(e),net.minecraft.core.Direction.UP,(net.minecraft.core.BlockPos)pos.invoke(e),false));}catch(ReflectiveOperationException ex){throw new IllegalStateException(ex);}}));}catch(ClassNotFoundException ignored){}catch(ReflectiveOperationException e){throw new IllegalStateException("SBW projectile hit API changed",e);}}
 private static Method find(Class<?>c,String...names){for(var n:names)try{return c.getMethod(n);}catch(NoSuchMethodException ignored){}return null;}
 private static double value(Entity e,Method method,double fallback){if(method==null)return fallback;try{Object v=method.invoke(e);return v instanceof Number n?n.doubleValue():fallback;}catch(ReflectiveOperationException ex){return fallback;}}
 public static void impact(Entity projectile,BlockHitResult hit){if(projectile.level()instanceof ServerLevel pbLevel&&pbLevel.getBlockState(hit.getBlockPos()).getBlock()instanceof Pb01Block){Pb01Protection.impact(projectile,hit);return;}if(!(projectile.level()instanceof ServerLevel l)||Ps01Config.IMPACT_WEAR.get()<=0)return;var state=l.getBlockState(hit.getBlockPos());if(!(state.getBlock()instanceof Ps01Block))return;var root=Ps01Block.main(l,hit.getBlockPos(),state);if(root==null)return;var methods=METHODS.computeIfAbsent(projectile.getClass(),c->new Method[]{find(c,"getDamage","getBaseDamage"),find(c,"getExplosionRadius","getExplosionRadiusValue")});if(value(projectile,methods[1],0)>0)return;boolean leaf=root.doorHealth>0&&Ps01Geometry.leafAt(Ps01Geometry.local(root.getBlockPos(),root.facing(),hit.getLocation()),root.doorStep());var n=projectile.getPersistentData();long key=root.getBlockPos().asLong();long tick=l.getGameTime();String suffix=leaf?"Door":"Body";if(n.contains("PsHitTime"+suffix)&&n.getLong("PsHitTime"+suffix)==tick&&n.getLong("PsHitRoot"+suffix)==key)return;var direction=projectile.getDeltaMovement().normalize();var origin=hit.getLocation().subtract(direction.scale(.12));n.putLong("PsCoverTime",tick);n.putDouble("PsCoverX",origin.x);n.putDouble("PsCoverY",origin.y);n.putDouble("PsCoverZ",origin.z);n.putLong("PsHitTime"+suffix,tick);n.putLong("PsHitRoot"+suffix,key);
  Entity owner=projectile instanceof net.minecraft.world.entity.projectile.Projectile p?p.getOwner():null;if(owner instanceof ServerPlayer p){if(!l.mayInteract(p,hit.getBlockPos()))return;var event=new net.minecraftforge.event.level.BlockEvent.BreakEvent(l,hit.getBlockPos(),state,p);boolean prior=CHECKING.get();CHECKING.set(true);try{if(net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(event))return;}finally{CHECKING.set(prior);}}
  root.hit(Math.min(60,Math.max(.5,value(projectile,methods[0],4)*Ps01Config.IMPACT_WEAR.get())),leaf,hit.getLocation());
 }
 private Ps01Compat(){}
}
